.btn.danger,
button.danger {
  background: var(--danger);
}

.btn.danger:hover,
button.danger:hover {
  background: var(--danger-dark);
}

.inline-form {
  display: inline;
}

.actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  align-items: center;
}

.form {
  max-width: 620px;
}

label {
  display: block;
  font-weight: 700;
  margin: 14px 0 6px;
}

input,
textarea,
select {
  width: 100%;
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 11px 12px;
  font-size: 16px;
  font-family: inherit;
  background: white;
}

textarea {
  min-height: 140px;
  resize: vertical;
}

.flash {
  border-radius: 12px;
  padding: 12px 14px;
  margin-bottom: 18px;
  font-weight: 700;
}

.flash.success {
  background: #e8f7ef;
  color: var(--success);
  border: 1px solid #bce8ce;
}

.flash.error {
  background: #ffecec;
  color: var(--danger);
  border: 1px solid #ffcaca;
}

.table-wrap {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  background: var(--card);
}

th,
td {
  border-bottom: 1px solid var(--border);
  text-align: left;
  padding: 12px;
  vertical-align: top;
}

th {
  color: var(--muted);
  font-size: 14px;
}

.empty {
  text-align: center;
  padding: 34px;
  color: var(--muted);
}

.footer {
  text-align: center;
  color: var(--muted);
  padding: 24px;
  font-size: 14px;
}

@media (max-width: 900px) {
  .grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .hero h1 {
    font-size: 28px;
  }
}

@media (max-width: 640px) {
  .nav {
    align-items: flex-start;
    flex-direction: column;
  }

  .nav-links {
    justify-content: flex-start;
  }

  .grid {
    grid-template-columns: 1fr;
  }

  .hero {
    padding: 24px;
  }

  .hero h1 {
    font-size: 24px;
  }

  .card {
    padding: 18px;
  }

  .actions {
    flex-direction: column;
    align-items: stretch;
  }

  .actions .btn,
  .actions button {
    width: 100%;
    text-align: center;
  }
}

